# F[r][p2][p1]: total waviness produced inside all 10^r suffixes of length r that follow a
# started prefix whose last two digits are p2, p1 (p2 == 10 means only p1 has been placed).
_MAX_DIGITS = 16
_POW10 = [10 ** i for i in range(_MAX_DIGITS + 1)]
_F = [[[0] * 10 for _ in range(11)] for _ in range(_MAX_DIGITS + 1)]
for _r in range(1, _MAX_DIGITS + 1):
    for _p2 in range(11):
        for _p1 in range(10):
            total = 0
            for _d in range(10):
                if _p2 != 10 and ((_p1 > _p2 and _p1 > _d) or (_p1 < _p2 and _p1 < _d)):
                    total += _POW10[_r - 1]          # p1 becomes a peak or valley
                total += _F[_r - 1][_p1][_d]
            _F[_r][_p2][_p1] = total


def _waviness_upto(x: int) -> int:
    """Sum of waviness over every integer in [1, x]."""
    if x < 100:
        return 0
    digits = [int(c) for c in str(x)]
    n = len(digits)
    total = 0
    # numbers with fewer digits than x: a non zero first digit, then free digits
    for length in range(3, n):
        for first in range(1, 10):
            for second in range(10):
                total += _F[length - 2][first][second]
    # numbers with exactly n digits that are <= x
    prefix_wav = 0      # peaks and valleys already completed inside the fixed prefix
    p2, p1 = 10, 10
    for i, cur in enumerate(digits):
        rest = n - i - 1
        for d in range(1 if i == 0 else 0, cur):
            gained = 0
            if p2 != 10 and ((p1 > p2 and p1 > d) or (p1 < p2 and p1 < d)):
                gained = 1
            total += (prefix_wav + gained) * _POW10[rest]
            total += _F[rest][p1][d]          # free suffix after the prefix ending p1, d
        if p2 != 10 and ((p1 > p2 and p1 > cur) or (p1 < p2 and p1 < cur)):
            prefix_wav += 1
        p2, p1 = p1, cur
    return total + prefix_wav      # x itself


def total_waviness(num1: int, num2: int) -> int:
    return _waviness_upto(num2) - _waviness_upto(num1 - 1)

