def shortest_superstring(words: list[str]) -> str:
    n = len(words)
    # overlap[i][j]: longest suffix of words[i] that is a prefix of words[j]
    overlap = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j:
                a, b = words[i], words[j]
                for k in range(min(len(a), len(b)), 0, -1):
                    if a.endswith(b[:k]):
                        overlap[i][j] = k
                        break

    full = 1 << n
    INF = float("inf")
    dp = [[INF] * n for _ in range(full)]      # shortest length covering mask, ending in last
    parent = [[-1] * n for _ in range(full)]
    for i in range(n):
        dp[1 << i][i] = len(words[i])
    for mask in range(full):
        for last in range(n):
            cur = dp[mask][last]
            if cur == INF:
                continue
            for nxt in range(n):
                if mask >> nxt & 1:
                    continue
                new_mask = mask | (1 << nxt)
                cost = cur + len(words[nxt]) - overlap[last][nxt]
                if cost < dp[new_mask][nxt]:
                    dp[new_mask][nxt] = cost
                    parent[new_mask][nxt] = last

    # rebuild the ordering from the cheapest complete state
    last = min(range(n), key=lambda i: dp[full - 1][i])
    order = []
    mask = full - 1
    while last != -1:
        order.append(last)
        prev = parent[mask][last]
        mask ^= 1 << last
        last = prev
    order.reverse()

    result = words[order[0]]
    for a, b in zip(order, order[1:]):
        result += words[b][overlap[a][b]:]     # append only the non overlapping tail
    return result

