def path_existence_queries(n: int, nums: list[int], maxDiff: int, queries: list[list[int]]) -> list[int]:
    order = sorted(range(n), key=lambda i: nums[i])
    pos = [0] * n                       # node -> sorted position
    for p, node in enumerate(order):
        pos[node] = p
    vals = [nums[i] for i in order]

    # far[p]: furthest sorted position reachable from p in one edge
    far = [0] * n
    j = 0
    for p in range(n):
        if j < p:
            j = p
        while j + 1 < n and vals[j + 1] - vals[p] <= maxDiff:
            j += 1
        far[p] = j

    levels = max(1, n.bit_length())
    jump = [far]                        # jump[k][p]: position after 2^k greedy jumps
    for _ in range(1, levels):
        prev = jump[-1]
        jump.append([prev[prev[p]] for p in range(n)])

    answers = []
    for u, v in queries:
        if u == v:
            answers.append(0)
            continue
        a, b = sorted((pos[u], pos[v]))
        cur, steps = a, 0
        for k in range(levels - 1, -1, -1):
            if jump[k][cur] < b:
                cur = jump[k][cur]
                steps += 1 << k
        answers.append(steps + 1 if far[cur] >= b else -1)
    return answers

