class GridMaster:
    """Judge object. The grid, the start and the target are hidden from your code."""
    _DIRS = {"U": (-1, 0), "D": (1, 0), "L": (0, -1), "R": (0, 1)}

    def __init__(self, grid, r1, c1, r2, c2):
        self._grid = grid
        self._r, self._c = r1, c1
        self._target = (r2, c2)
        self._calls = 0
        self._limit = 60 * len(grid) * len(grid[0]) + 200

    def _tick(self):
        self._calls += 1
        if self._calls > self._limit:
            raise _TooManyGridCalls()

    def _next(self, direction):
        dr, dc = self._DIRS[direction]
        r, c = self._r + dr, self._c + dc
        if 0 <= r < len(self._grid) and 0 <= c < len(self._grid[0]) and self._grid[r][c] != 0:
            return r, c
        return None

    def canMove(self, direction: str) -> bool:
        self._tick()
        return self._next(direction) is not None

    def move(self, direction: str) -> int:
        self._tick()
        nxt = self._next(direction)
        if nxt is None:
            return -1
        self._r, self._c = nxt
        return self._grid[nxt[0]][nxt[1]]

    def isTarget(self) -> bool:
        self._tick()
        return (self._r, self._c) == self._target

