def find_shortest_path(master: "GridMaster") -> int:
    DIRS = {"U": (-1, 0), "D": (1, 0), "L": (0, -1), "R": (0, 1)}
    BACK = {"U": "D", "D": "U", "L": "R", "R": "L"}

    # phase 1: explore the reachable area; the start is (0, 0) and costs nothing
    cost = {(0, 0): 0}
    target = (0, 0) if master.isTarget() else None
    stack = [[(0, 0), iter("UDLR"), None]]      # cell, remaining directions, direction used to enter it
    while stack:
        (r, c), directions, entered_by = stack[-1]
        for d in directions:
            dr, dc = DIRS[d]
            nxt = (r + dr, c + dc)
            if nxt in cost or not master.canMove(d):
                continue
            cost[nxt] = master.move(d)
            if master.isTarget():
                target = nxt
            stack.append([nxt, iter("UDLR"), d])
            break
        else:
            stack.pop()
            if entered_by is not None:
                master.move(BACK[entered_by])    # walk back to the parent cell
    if target is None:
        return -1

    # phase 2: Dijkstra over the discovered cells
    dist = {(0, 0): 0}
    heap = [(0, 0, 0)]
    while heap:
        d, r, c = heapq.heappop(heap)
        if (r, c) == target:
            return d
        if d > dist[(r, c)]:
            continue
        for dr, dc in DIRS.values():
            nxt = (r + dr, c + dc)
            if nxt in cost:
                nd = d + cost[nxt]
                if nd < dist.get(nxt, math.inf):
                    dist[nxt] = nd
                    heapq.heappush(heap, (nd, nxt[0], nxt[1]))
    return -1

def repeated_character(s: str) -> str:
    seen = 0
    for ch in s:
        bit = 1 << (ord(ch) - ord("a"))
        if seen & bit:
            return ch           # first letter met for the second time
        seen |= bit
    return ""                   # unreachable: the input always has a repeat

def minimum_score(s: str, t: str) -> int:
    n, m = len(s), len(t)
    # left[i]: index in s where t[i - 1] lands when t[:i] is matched as early as possible
    left = [math.inf] * (m + 1)
    left[0] = -1
    i = 0
    for p, ch in enumerate(s):
        if i < m and ch == t[i]:
            i += 1
            left[i] = p
    if i == m:
        return 0                          # t already fits in s
    # right[j]: index in s where t[j] lands when t[j:] is matched as late as possible
    right = [-1] * (m + 1)
    right[m] = n
    j = m
    for p in range(n - 1, -1, -1):
        if j > 0 and s[p] == t[j - 1]:
            j -= 1
            right[j] = p
    best = m
    j = 0
    for i in range(m + 1):
        if left[i] == math.inf:
            break
        if j < i:
            j = i
        while j <= m and right[j] <= left[i]:
            j += 1
        if j > m:
            break
        best = min(best, j - i)
    return best

def min_end(n: int, x: int) -> int:
    result = x
    free = n - 1            # the bits to scatter into the zero positions of x
    bit = 0                 # current position in result
    while free:
        if not (x >> bit) & 1:
            # zero bit of x: receive the lowest remaining bit of n - 1
            if free & 1:
                result |= 1 << bit
            free >>= 1
        bit += 1
    return result

def number_of_special_substrings(s: str) -> int:
    last_seen = {}
    left = 0
    total = 0
    for right, ch in enumerate(s):
        if last_seen.get(ch, -1) >= left:
            left = last_seen[ch] + 1       # exclude the earlier copy of ch
        last_seen[ch] = right
        total += right - left + 1          # special substrings ending at right
    return total

def min_operations(nums: List[int], k: int) -> int:
    # Each removal takes the smallest value, so exactly the elements below k are removed.
    return sum(1 for x in nums if x < k)

def check_partitioning(s: str) -> bool:
    n = len(s)
    # same_char[c]: bit r is set when s[r] == c
    same_char = {}
    for r, ch in enumerate(s):
        same_char[ch] = same_char.get(ch, 0) | (1 << r)

    # row[l]: bit r is set when s[l..r] is a palindrome (built from the right)
    row = [0] * (n + 1)
    for l in range(n - 1, -1, -1):
        inner = (row[l + 1] << 1) | (1 << l) | (1 << (l + 1))   # inner part is a palindrome or empty
        row[l] = same_char[s[l]] & inner & ((1 << n) - 1)

    # good_end: bit r set when the suffix s[r+1..n-1] is a non empty palindrome
    good_end = 0
    for r in range(n - 1):
        if row[r + 1] >> (n - 1) & 1:
            good_end |= 1 << r

    for i in range(n - 2):
        if row[0] >> i & 1:                     # s[0..i] is a palindrome
            if row[i + 1] & good_end:           # a palindromic middle meets a palindromic suffix
                return True
    return False

def most_competitive(nums: List[int], k: int) -> List[int]:
    n = len(nums)
    stack = []
    for i, x in enumerate(nums):
        # Pop larger values while enough elements remain to still reach k picks.
        while stack and stack[-1] > x and len(stack) + (n - i) > k:
            stack.pop()
        stack.append(x)
    return stack[:k]
